// Tiny billing/files service.
const http = require("http");
const { exec } = require("child_process");
const fs = require("fs");
const path = require("path");

const SESSIONS = { "tok-alice": "alice", "tok-bob": "bob" };
const INVOICES = {
  1: { owner: "alice", amount: 120 },
  2: { owner: "bob", amount: 9800 },
};
const USERS = { alice: { email: "alice@example.test" }, bob: { email: "bob@example.test" } };
const FILE_ROOT = path.join(__dirname, "public");

function currentUser(req) {
  const auth = req.headers["authorization"] || "";
  return SESSIONS[auth.replace(/^Bearer /, "")] || null;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  const user = currentUser(req);
  if (!user) {
    res.writeHead(401).end("login required");
    return;
  }

  if (url.pathname === "/me") {
    res.end(JSON.stringify({ user, ...USERS[user] }));
    return;
  }

  const m = url.pathname.match(/^\/invoices\/(\d+)$/);
  if (m) {
    const inv = INVOICES[m[1]];
    if (!inv) return res.writeHead(404).end();
    res.end(JSON.stringify(inv));
    return;
  }

  if (url.pathname === "/ping") {
    const host = url.searchParams.get("host") || "127.0.0.1";
    exec(`ping -c 1 ${host}`, (err, out) => res.end(out || String(err)));
    return;
  }

  if (url.pathname === "/files") {
    const name = url.searchParams.get("name") || "index.txt";
    fs.readFile(path.join(FILE_ROOT, name), (err, data) => {
      if (err) return res.writeHead(404).end();
      res.end(data);
    });
    return;
  }

  res.writeHead(404).end();
});

if (require.main === module) server.listen(3000, "127.0.0.1");
module.exports = server;

