31	  };
32	  const value = {
33	    coverage_id: canonicalCoverageId(canonicalRefs),
34	    canonical_refs: canonicalRefs,
35	    surface: "Update-user route",
36	    boundary: "Object ownership",
37	    subsystem: "API",
38	    attack_class: "Access control",
39	    starting_paths: ["src/router.ts", "src/authz.ts"],
40	    ordinary_attack_class_block: "ATTACK-CLASSES.md#Access control",
41	    selected_companion_blocks: [],
42	    excluded_blocks: [{ block: "WEB-PROTOCOL-AND-AUTH.md#Cache behavior", reason: "The route is not cached." }],
