60	function runCli(contents, options = {}) {
61	  const { nodeArgs = [], timeout = CLI_TIMEOUT_MS } = options;
62	  const directory = fs.mkdtempSync(path.join(os.tmpdir(), "validate-coverage-ledger-"));
63	  const ledgerPath = path.join(directory, "coverage-ledger.json");
64	  try {
65	    fs.writeFileSync(ledgerPath, contents);
66	    return spawnSync(process.execPath, [...nodeArgs, validatorPath, ledgerPath], {
67	      encoding: "utf8",
68	      timeout,
69	    });
70	  } finally {
71	    fs.rmSync(directory, { recursive: true, force: true });
72	  }
73	}
