169	test("text preflight enforces structural cardinality limits", () => {
170	  const depthLimit = LIMITS.nestingDepth;
171	  assert.doesNotThrow(() => preflightJsonText(`${"[".repeat(depthLimit)}0${"]".repeat(depthLimit)}`));
172	  assert.throws(
173	    () => preflightJsonText(`${"[".repeat(depthLimit + 1)}0${"]".repeat(depthLimit + 1)}`),
174	    /exceeds nesting depth limit 64/,
175	  );
176	
177	  const tooManyUnits = `[${"null,".repeat(LIMITS.units)}null]`;
178	  assert.throws(() => preflightJsonText(tooManyUnits), /exceeds 10000 top-level unit limit/);
179	
180	  const tooManyItems = `[[${"null,".repeat(LIMITS.collectionItems)}null]]`;
181	  assert.throws(() => preflightJsonText(tooManyItems), /exceeds 1000 item array limit/);
