 1	// Tiny billing/files service.
 2	const http = require("http");
 3	const { exec } = require("child_process");
 4	const fs = require("fs");
 5	const path = require("path");
 6	
 7	const SESSIONS = { "tok-alice": "alice", "tok-bob": "bob" };
 8	const INVOICES = {
 9	  1: { owner: "alice", amount: 120 },
10	  2: { owner: "bob", amount: 9800 },
11	};
12	const USERS = { alice: { email: "alice@example.test" }, bob: { email: "bob@example.test" } };
13	const FILE_ROOT = path.join(__dirname, "public");
14	
15	function currentUser(req) {
16	  const auth = req.headers["authorization"] || "";
17	  return SESSIONS[auth.replace(/^Bearer /, "")] || null;
18	}
19	
20	const server = http.createServer((req, res) => {
21	  const url = new URL(req.url, "http://localhost");
22	  const user = currentUser(req);
23	  if (!user) {
24	    res.writeHead(401).end("login required");
25	    return;
26	  }
27	
28	  if (url.pathname === "/me") {
29	    res.end(JSON.stringify({ user, ...USERS[user] }));
30	    return;
31	  }
32	
33	  const m = url.pathname.match(/^\/invoices\/(\d+)$/);
34	  if (m) {
35	    const inv = INVOICES[m[1]];
36	    if (!inv) return res.writeHead(404).end();
37	    res.end(JSON.stringify(inv));
38	    return;
39	  }
40	
41	  if (url.pathname === "/ping") {
42	    const host = url.searchParams.get("host") || "127.0.0.1";
43	    exec(`ping -c 1 ${host}`, (err, out) => res.end(out || String(err)));
44	    return;
45	  }
46	
47	  if (url.pathname === "/files") {
